Fixes: f8db6475a836 ("macvlan: fix error recovery in macvlan_common_newlink()")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reported-by: valis <sec@valis.email>
Link: https://patch.msgid.link/20260213142557.3059043-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is a use-after-free race condition in the macvlan driver's `macvlan_common_newlink()` error path. When an error is detected after the new network device (`dev`) has been made visible to RCU readers (e.g., through `netdev_master_upper_dev_link`), the caller `rtnl_newlink()` directly frees the device using `free_netdev()` without waiting for an RCU grace period. This allows concurrent RCU read-side critical sections (such as `macvlan_forward_source()`) to access the freed device, leading to a slab-use-after-free. The patch fixes this by adding `synchronize_net()` before returning the error, ensuring all prior RCU readers have completed.

Here is the patch:

 int macvlan_common_newlink(struct net_device *dev,
 			   struct rtnl_newlink_params *params,
 			   struct netlink_ext_ack *extack)
 {
 	struct net *link_net = rtnl_newlink_link_net(params);
 	struct macvlan_dev *vlan = netdev_priv(dev);
 	struct nlattr **data = params->data;
 	struct nlattr **tb = params->tb;
 	struct net_device *lowerdev;
 	struct macvlan_port *port;
 	bool create = false;
 	int macmode;
 	int err;

 	if (!tb[IFLA_LINK])
 		return -EINVAL;

 	lowerdev = __dev_get_by_index(link_net, nla_get_u32(tb[IFLA_LINK]));
 	if (lowerdev == NULL)
 		return -ENODEV;

 	/* When creating macvlans or macvtaps on top of other macvlans - use
 	 * the real device as the lowerdev.
 	 */
 	if (netif_is_macvlan(lowerdev))
 		lowerdev = macvlan_dev_real_dev(lowerdev);

 	if (!tb[IFLA_MTU])
 		dev->mtu = lowerdev->mtu;
 	else if (dev->mtu > lowerdev->mtu)
 		return -EINVAL;

 	/* MTU range: 68 - lowerdev->max_mtu */
 	dev->min_mtu = ETH_MIN_MTU;
 	dev->max_mtu = lowerdev->max_mtu;

 	if (!tb[IFLA_ADDRESS])
 		eth_hw_addr_random(dev);

 	if (!netif_is_macvlan_port(lowerdev)) {
 		err = macvlan_port_create(lowerdev);
 		if (err < 0)
 			return err;
 		create = true;
 	}
 	port = macvlan_port_get_rtnl(lowerdev);

 	/* Only 1 macvlan device can be created in passthru mode */
 	if (macvlan_passthru(port)) {
 		/* The macvlan port must be not created this time,
 		 * still goto destroy_macvlan_port for readability.
 		 */
 		err = -EINVAL;
 		goto destroy_macvlan_port;
 	}

 	vlan->lowerdev = lowerdev;
 	vlan->dev      = dev;
 	vlan->port     = port;
 	vlan->set_features = MACVLAN_FEATURES;

 	vlan->mode     = MACVLAN_MODE_VEPA;
 	if (data && data[IFLA_MACVLAN_MODE])
 		vlan->mode = nla_get_u32(data[IFLA_MACVLAN_MODE]);

 	if (data && data[IFLA_MACVLAN_FLAGS])
 		vlan->flags = nla_get_u16(data[IFLA_MACVLAN_FLAGS]);

 	if (vlan->mode == MACVLAN_MODE_PASSTHRU) {
 		if (port->count) {
 			err = -EINVAL;
 			goto destroy_macvlan_port;
 		}
 		macvlan_set_passthru(port);
 		eth_hw_addr_inherit(dev, lowerdev);
 	}

 	if (data && data[IFLA_MACVLAN_MACADDR_MODE]) {
 		if (vlan->mode != MACVLAN_MODE_SOURCE) {
 			err = -EINVAL;
 			goto destroy_macvlan_port;
 		}
 		macmode = nla_get_u32(data[IFLA_MACVLAN_MACADDR_MODE]);
 		err = macvlan_changelink_sources(vlan, macmode, data);
 		if (err)
 			goto destroy_macvlan_port;
 	}

 	vlan->bc_queue_len_req = MACVLAN_DEFAULT_BC_QUEUE_LEN;
 	if (data && data[IFLA_MACVLAN_BC_QUEUE_LEN])
 		vlan->bc_queue_len_req = nla_get_u32(data[IFLA_MACVLAN_BC_QUEUE_LEN]);

 	if (data && data[IFLA_MACVLAN_BC_CUTOFF])
 		update_port_bc_cutoff(
 			vlan, nla_get_s32(data[IFLA_MACVLAN_BC_CUTOFF]));

 	err = register_netdevice(dev);
 	if (err < 0)
 		goto destroy_macvlan_port;

 	dev->priv_flags |= IFF_MACVLAN;
 	err = netdev_upper_dev_link(lowerdev, dev, extack);
 	if (err)
 		goto unregister_netdev;

 	list_add_tail_rcu(&vlan->list, &port->vlans);
 	update_port_bc_queue_len(vlan->port);
 	netif_stacked_transfer_operstate(lowerdev, dev);
 	linkwatch_fire_event(dev);

 	return 0;

 unregister_netdev:
 	/* macvlan_uninit would free the macvlan port */
 	unregister_netdevice(dev);
 	return err;
 destroy_macvlan_port:
 	/* the macvlan port may be freed by macvlan_uninit when fail to register.
 	 * so we destroy the macvlan port only when it's valid.
 	 */
 	if (macvlan_port_get_rtnl(lowerdev)) {
 		macvlan_flush_sources(port, vlan);
 		if (create)
 			macvlan_port_destroy(port->dev);
 	}
+	/* @dev might have been made visible before an error was detected.
+	 * Make sure to observe an RCU grace period before our caller
+	 * (rtnl_newlink()) frees it.
+	 */
+	synchronize_net();
 	return err;
 }
 EXPORT_SYMBOL_GPL(macvlan_common_newlink);


